import React, { createContext, useContext, useState, type ReactNode } from 'react';

// --- Private Context ---
interface ChatMessageCtx {
  isExpanded: boolean;
  role: 'user' | 'assistant';
  toggleExpanded: () => void;
}
const ChatMessageContext = createContext<ChatMessageCtx | null>(null);

function useChatMessageCtx() {
  const ctx = useContext(ChatMessageContext);
  if (!ctx) throw new Error('Must be used inside <ChatMessage>');
  return ctx;
}

// --- Root ---
function ChatMessage({ role, children }: { role: 'user' | 'assistant'; children: ReactNode }) {
  const [isExpanded, setIsExpanded] = useState(false);
  return (
    <ChatMessageContext.Provider value={{ isExpanded, role, toggleExpanded: () => setIsExpanded((p) => !p) }}>
      <div className={`rounded-lg p-4 ${role === 'user' ? 'bg-accent-subtle ml-8' : 'bg-canvas-subtle mr-8'}`}>
        {children}
      </div>
    </ChatMessageContext.Provider>
  );
}

// --- Sub-components ---
ChatMessage.Content = function Content({ children }: { children: ReactNode }) {
  const { isExpanded } = useChatMessageCtx();
  return <div className={isExpanded ? '' : 'line-clamp-5'}>{children}</div>;
};

ChatMessage.Actions = function Actions() {
  const { isExpanded, toggleExpanded } = useChatMessageCtx();
  return (
    <button type="button" onClick={toggleExpanded} className="text-xs text-fg-muted hover:text-fg-default mt-2">
      {isExpanded ? 'Show less' : 'Show more'}
    </button>
  );
};

// Usage: clean, self-documenting consumer JSX
// <ChatMessage role="assistant">
//   <ChatMessage.Content><MarkdownRenderer content={message.text} /></ChatMessage.Content>
//   <ChatMessage.Actions />
// </ChatMessage>

import { useState } from 'react';

interface ConversationFilterProps {
  // When provided → Controlled mode
  value?: string;
  onChange?: (value: string) => void;
  // Default starting value for Uncontrolled mode
  defaultValue?: string;
}

export function ConversationFilter({ value, onChange, defaultValue = '' }: ConversationFilterProps) {
  const isControlled = value !== undefined;
  const [internalValue, setInternalValue] = useState(defaultValue);

  const currentValue = isControlled ? value : internalValue;

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!isControlled) setInternalValue(e.target.value);
    onChange?.(e.target.value);
  };

  return (
    <input
      type="search"
      value={currentValue}
      onChange={handleChange}
      placeholder="Filter conversations..."
      className="w-full px-3 py-2 rounded border border-border bg-canvas-default text-fg-default"
    />
  );
}
